export function translator(locale) {
  const dict = STRINGS[locale] || STRINGS.ko;
  return (key) => dict[key] ?? EN[key] ?? key;
}

export function localeLabel(locale) {
  return {
    ko: '한국어',
    en: 'English',
    ja: '日本語',
    zh: '中文',
    hi: 'हिन्दी',
    de: 'Deutsch',
    fr: 'Français',
    es: 'Español',
    pt: 'Português',
    ar: 'العربية',
    id: 'Bahasa Indonesia'
  }[locale] || locale;
}
